"""Public-route transaction census. Instrumented nested windows, not throughput."""
import collections,contextvars,json,runpy,time
from pathlib import Path
from hipengine.core.hip import HipRuntime
from hipengine.runtime.qwen4_exp_runner import Qwen4ExpDecodeState,Qwen4ExpGGUFResidentModelRunner as Runner
from hipengine.generation.qwen4_exp_serving_mtp import Qwen4ExpServingMTP
OUT=Path('/tmp/qwen38fn-mtp-state-20261022/transaction-census.json')
active=contextvars.ContextVar('transaction_census',default=None)
report={'diagnostic':'Nested synchronized phase windows; not additive or throughput evidence','cycles':[]}
def phase(owner,name):
 original=getattr(owner,name)
 def call(self,*args,**kwargs):
  record=active.get()
  if record is None:return original(self,*args,**kwargs)
  self.runtime.device_synchronize();start=time.perf_counter();record['stack'].append(name)
  try:return original(self,*args,**kwargs)
  finally:
   self.runtime.device_synchronize();record['stack'].pop();record['phases'].append({'name':name,'ms':1000*(time.perf_counter()-start),'reuse_snapshot':kwargs.get('reuse_snapshot'),'consumed':args[0] if name=='commit_target_block_rows' and args else None})
 setattr(owner,name,call)
for name in ('begin_device_transaction','rollback_device_transaction','commit_device_transaction','verify_target_block_state_rows','commit_target_block_rows','_verify_rows_workspace'):phase(Runner,name)
for name in ('device_snapshot','restore_device_snapshot'):phase(Qwen4ExpDecodeState,name)
def copies(name):
 original=getattr(HipRuntime,name)
 def call(self,*args,**kwargs):
  record=active.get()
  if record is None:return original(self,*args,**kwargs)
  start=time.perf_counter()
  try:return original(self,*args,**kwargs)
  finally:
   label=(record['stack'][-1] if record['stack'] else 'cycle')+'/'+name+'/'+str(int(args[3]))
   item=record['copies'].setdefault(label,{'calls':0,'bytes':0,'host_ms':0});item['calls']+=1;item['bytes']+=int(args[2]);item['host_ms']+=1000*(time.perf_counter()-start)
 setattr(HipRuntime,name,call)
for name in ('memcpy','memcpy_async'):copies(name)
original=Qwen4ExpServingMTP._advance_mtp
def cycle(self,row,budget,**kwargs):
 record={'request_id':row.request_id,'prompt_tokens':len(row.prompt_ids),'start_position':int(row.runner.position),'budget':budget,'state_bytes':dict(row.runner.state.nbytes_by_owner),'phases':[],'copies':{},'stack':[]}
 token=active.set(record);start=time.perf_counter()
 try:return original(self,row,budget,**kwargs)
 finally:
  record['instrumented_wall_ms']=1000*(time.perf_counter()-start);record.pop('stack');active.reset(token);report['cycles'].append(record);OUT.write_text(json.dumps(report,indent=2)+'\n')
Qwen4ExpServingMTP._advance_mtp=cycle
runpy.run_module('hipengine.server',run_name='__main__')

